// `npm run gen`: regenerate every committed generated file from its one source.
//
// - schema/*.schema.json from the core's Pydantic models (ADR 0005);
// - schema/output.d.ts, the UI's TS types, from the output schema;
// - app/src/product.ts, the UI's product-name constant, from `productName` in
//   app/src-tauri/tauri.conf.json (the canonical display name).
//
// `--check` writes nothing and fails if any file is stale; `npm run lint` runs it, so CI
// rejects drift.

import { execFileSync } from "node:child_process";
import { readFileSync, writeFileSync } from "node:fs";
import { dirname, join } from "node:path";
import { fileURLToPath } from "node:url";

import { compile } from "json-schema-to-typescript";

const root = join(dirname(fileURLToPath(import.meta.url)), "..");
const check = process.argv.includes("--check");

const GENERATED = "Generated by `npm run gen`. Do not edit by hand.";

async function generate() {
  const files = new Map();

  const schemas = JSON.parse(
    execFileSync(
      "uv",
      [
        "run",
        "--project",
        "core",
        "--quiet",
        "python",
        "-m",
        "versionbar.contract",
      ],
      { cwd: root, encoding: "utf8", stdio: ["ignore", "pipe", "inherit"] },
    ),
  );
  for (const [name, schema] of Object.entries(schemas)) {
    files.set(join("schema", name), `${JSON.stringify(schema, null, 2)}\n`);
  }

  const types = await compile(schemas["output.schema.json"], "CommandOutput", {
    bannerComment: `// ${GENERATED} Source: schema/output.schema.json.`,
    // Every output object forbids unknown keys, so no index signatures are wanted.
    additionalProperties: false,
    // Self-contained output: nothing reaches outside the schema file.
    $refOptions: { resolve: { external: false } },
  });
  files.set(join("schema", "output.d.ts"), types);

  const tauri = JSON.parse(
    readFileSync(join(root, "app", "src-tauri", "tauri.conf.json"), "utf8"),
  );
  files.set(
    join("app", "src", "product.ts"),
    [
      `// ${GENERATED}`,
      "// The one place the UI names the product. The name is provisional: its source is",
      "// `productName` in src-tauri/tauri.conf.json, and everything in the UI derives from it.",
      `export const PRODUCT_NAME = ${JSON.stringify(tauri.productName)};`,
      "",
    ].join("\n"),
  );

  return files;
}

function current(path) {
  try {
    const text = readFileSync(join(root, path), "utf8");
    // Writing restores LF; checking accepts a CRLF checkout of the same content.
    return check ? text.replaceAll("\r\n", "\n") : text;
  } catch {
    return null;
  }
}

const files = await generate();
const stale = [...files]
  .filter(([path, text]) => current(path) !== text)
  .map(([path]) => path);

if (check) {
  if (stale.length > 0) {
    console.error(
      `Stale generated files (run \`npm run gen\`):\n  ${stale.join("\n  ")}`,
    );
    process.exit(1);
  }
} else {
  for (const path of stale) {
    writeFileSync(join(root, path), files.get(path));
    console.log(`wrote ${path}`);
  }
}
